<?php namespace Vedairo\I18n; final class Translator {private array $data=[];public function load(string $locale,array $data):void{$this->data[$locale]=$data;}public function get(string $key,?string $locale=null,array $replace=[]):string{$locale=$locale?:env('APP_LOCALE','en');$v=$this->data[$locale][$key]??$key;foreach($replace as $k=>$x)$v=str_replace(':'.$k,(string)$x,$v);return $v;}}
